41	const PROCESSING_FEE = 5;
42	/** Levied on every quote, not only the customer's first — see the policy-wide modifier rules. */
43	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
44	
45	/** The MHPCO price list; only the types pinned down by tests so far. */
46	const BASE_PREMIUMS: Record<string, number> = {
47	  sword: 100,
48	  amulet: 60,
49	  staff: 80,
50	};
51	
52	/** Keeps binary floating-point drift from tipping an exact amount over a rounding boundary. */
53	const withoutFloatNoise = (amount: number): number => Number(amount.toFixed(6));
54	
55	/** Premiums are rounded in the MHPCO's favour: up to the next whole G. */
56	const roundUpToWholeG = (amount: number): number => Math.ceil(withoutFloatNoise(amount));
57	
58	const basePremiumFor = (item: Item): number => BASE_PREMIUMS[item.type];
59	
60	const sum = (amounts: number[]): number => amounts.reduce((total, amount) => total + amount, 0);
61	
62	const premiumFor = (items: Item[]): number => {
63	  const basePremium = sum(items.map(basePremiumFor));
64	  return roundUpToWholeG(basePremium * (1 + INITIAL_ASSESSMENT_SURCHARGE) + PROCESSING_FEE);
65	};
66	
67	export const runScenario = (scenario: Scenario): ScenarioResult => ({
68	  results: scenario.steps.map((step) => ({
69	    premium: premiumFor((step as QuoteStep).items),
70	  })),
71	});
